static int DecodeWord(DianaContext * pContext, unsigned int word, DianaParserResult * pResult)
{
    unsigned char bytes[4] = {(unsigned char)word, (unsigned char)(word >> 8), (unsigned char)(word >> 16), (unsigned char)(word >> 24)};
    DianaMemoryStream stream;
    Diana_InitMemoryStream(&stream, bytes, sizeof(bytes));
    return Diana_ParseCmd(pContext, Diana_GetRootLine(), &stream.parent.parent.parent, pResult);
}

static int DecodeA64(unsigned int word, DianaParserResult * pResult, const DianaArmProfile * pProfile = 0)
{
    DianaContext context;
    Diana_InitContextEx(&context, DIANA_MODE64, DIANA_ARCH_AARCH64);
    if (pProfile)
        Diana_SetArmProfile(&context, pProfile);
    return DecodeWord(&context, word, pResult);
}

static void TestRows(const ArmTextRow * pRows, size_t count, int options)
{
    diana::CMasmString text;
    text.SetOptions(options);
    DianaContext context;
    Diana_InitContextEx(&context, DIANA_MODE64, DIANA_ARCH_AARCH64);
    for (size_t i = 0; i < count; ++i)
    {
        DianaParserResult result;
        DIANA_TEST_ASSERT(DecodeWord(&context, pRows[i].word, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(result.iFullCmdSize == 4);
        const char * pText = text.Assign(&result, pRows[i].address);
        if (strcmp(pText, pRows[i].pText) != 0)
        {
            printf("arm64: %08x: expected \"%s\", got \"%s\"\n", pRows[i].word, pRows[i].pText, pText);
            DIANA_TEST_ASSERT(0);
        }
    }
}

static void test_arm64_text()
{
    TestRows(g_aliasRows, sizeof(g_aliasRows)/sizeof(g_aliasRows[0]), 0);
    TestRows(g_rawRows, sizeof(g_rawRows)/sizeof(g_rawRows[0]), DIANA_TEXT_OUTPUT_OPTION_ARM_NO_ALIASES);
    TestRows(g_curatedRows, sizeof(g_curatedRows)/sizeof(g_curatedRows[0]), 0);
    TestRows(g_curatedRawRows, sizeof(g_curatedRawRows)/sizeof(g_curatedRawRows[0]), DIANA_TEXT_OUTPUT_OPTION_ARM_NO_ALIASES);
}

static void test_arm64_operands()
{
    DianaParserResult result;

    // ldr x0, [x1, #8]!
    DIANA_TEST_ASSERT(DecodeA64(0xf8408c20, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 2);
    DIANA_TEST_ASSERT(result.linkedOperands[0].type == diana_register);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.recognizedRegister == reg_A64_X0);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_index);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.reg == reg_A64_X0 + 1);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.dispValue == 8);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.writeback == DIANA_ARM_WRITEBACK_PRE);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "ldr"));

    // stp x29, x30, [sp, #-16]!
    DIANA_TEST_ASSERT(DecodeA64(0xa9bf7bfd, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 3);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A64_X0 + 30);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.rmIndex.reg == reg_A64_SP);
    DIANA_TEST_ASSERT((long long)result.linkedOperands[2].value.rmIndex.dispValue == -16);

    // ldr x0, [x1, w2, sxtw #3]
    DIANA_TEST_ASSERT(DecodeA64(0xf862d820, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.indexed_reg == reg_A64_W0 + 2);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_EXTEND_SXTW);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftAmount == 3);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.index == 8);

    // add x0, sp, #0x10, the immediate and the SP
    DIANA_TEST_ASSERT(DecodeA64(0x910043e0, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A64_SP);
    DIANA_TEST_ASSERT(result.linkedOperands[2].type == diana_imm);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 0x10);

    // and w0, w1, #0xff: the bitmask immediate is decoded
    DIANA_TEST_ASSERT(DecodeA64(0x12001c20, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 0xff);

    // csel x0, x1, x2, ne
    DIANA_TEST_ASSERT(DecodeA64(0x9a821020, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[3].type == diana_arm_cond);
    DIANA_TEST_ASSERT(result.linkedOperands[3].arm.cond == 1);

    // ldr x0, <literal at +8>: [pc + offset], relative to the next instruction like x86 rip
    DIANA_TEST_ASSERT(DecodeA64(0x58000040, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_index);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.reg == reg_A64_PC);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.dispValue == 4);
}

static void TestJump(unsigned int word, OPERAND_SIZE address, int flags, int expectedResult, OPERAND_SIZE expectedTarget)
{
    DianaParserResult result;
    DIANA_TEST_ASSERT(DecodeA64(word, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.pInfo->m_pGroupInfo->m_pLinkedInfo != 0);
    DIANA_TEST_ASSERT(result.pInfo->m_pGroupInfo->m_pLinkedInfo->flags == flags);

    OPERAND_SIZE target = 0;
    int absolute = 0, data = 0;
    int status = Diana_AnalyzeJumps(&result, address + result.iFullCmdSize, &target, &absolute, &data);
    DIANA_TEST_ASSERT(status == expectedResult);
    if (status == DI_SUCCESS)
    {
        DIANA_TEST_ASSERT(target == expectedTarget);
        DIANA_TEST_ASSERT(!absolute);
    }
}

static void test_arm64_jumps()
{
    const int jmp = DIANA_GT_CAN_CHANGE_RIP|DIANA_GT_IS_JUMP;
    const int jcc = DIANA_GT_CAN_CHANGE_RIP|DIANA_GT_IS_JUMP|DIANA_GT_CAN_GO_TO_THE_NEXT_INSTRUCTION;
    const int call = DIANA_GT_CAN_CHANGE_RIP|DIANA_GT_IS_CALL|DIANA_GT_CAN_GO_TO_THE_NEXT_INSTRUCTION;
    const int ret = DIANA_GT_CAN_CHANGE_RIP|DIANA_GT_RET;

    TestJump(0x14000040, 0x1000, jmp, DI_SUCCESS, 0x1100);     // b 0x1100
    TestJump(0x17ffffff, 0x1000, jmp, DI_SUCCESS, 0xffc);      // b 0xffc
    TestJump(0x94000010, 0x2000, call, DI_SUCCESS, 0x2040);    // bl 0x2040
    TestJump(0x54000081, 0x3000, jcc, DI_SUCCESS, 0x3010);     // b.ne 0x3010
    TestJump(0xb4000060, 0x4000, jcc, DI_SUCCESS, 0x400c);     // cbz x0, 0x400c
    TestJump(0x37180060, 0x5000, jcc, DI_SUCCESS, 0x500c);     // tbnz w0, #3, 0x500c
    TestJump(0xd61f0200, 0x6000, jmp, DI_UNSUPPORTED_COMMAND, 0); // br x16
    TestJump(0xd63f0200, 0x6000, call, DI_UNSUPPORTED_COMMAND, 0); // blr x16
    TestJump(0xd65f03c0, 0x7000, ret, DI_NOT_FOUND, 0);       // ret

    // pointer authentication, hinted and compare-and-branch forms
    const int stop = DIANA_GT_CAN_CHANGE_RIP|DIANA_GT_STOP;
    TestJump(0x540000b1, 0x3000, jcc, DI_SUCCESS, 0x3014);     // bc.ne 0x3014
    TestJump(0x74020081, 0x8000, jcc, DI_SUCCESS, 0x8010);     // cbgt w1, w2, 0x8010
    TestJump(0xf4020081, 0x8000, jcc, DI_SUCCESS, 0x8010);     // cbgt x1, x2, 0x8010
    TestJump(0x74c2bfe1, 0x8000, jcc, DI_SUCCESS, 0x7ffc);     // cbbeq w1, w2, 0x7ffc
    TestJump(0x74e32001, 0x8000, jcc, DI_SUCCESS, 0x7c00);     // cbne w1, w3, 0x7c00 (imm9 = -256)
    TestJump(0x75018081, 0x8000, jcc, DI_SUCCESS, 0x8010);     // cbgt w1, #3, 0x8010
    TestJump(0xd71f0864, 0x6000, jmp, DI_UNSUPPORTED_COMMAND, 0); // braa x3, x4
    TestJump(0xd61f087f, 0x6000, jmp, DI_UNSUPPORTED_COMMAND, 0); // braaz x3
    TestJump(0xd63f085f, 0x6000, call, DI_UNSUPPORTED_COMMAND, 0); // blraaz x2
    TestJump(0xd73f0c64, 0x6000, call, DI_UNSUPPORTED_COMMAND, 0); // blrab x3, x4
    TestJump(0xd65f0bff, 0x7000, ret, DI_NOT_FOUND, 0);       // retaa
    TestJump(0xd69f0fff, 0x7000, ret, DI_NOT_FOUND, 0);       // eretab
    TestJump(0x550000bf, 0x7000, ret, DI_NOT_FOUND, 0);       // retaasppc: the label is not a target
    TestJump(0xd65f0be3, 0x7000, ret, DI_NOT_FOUND, 0);       // retaasppcr x3
    TestJump(0xd6ff07e0, 0x7000, ret, DI_NOT_FOUND, 0);       // texit nb
    // no next instruction and no target
    TestJump(0xd4200020, 0x7000, stop, DI_NOT_FOUND, 0);      // brk #0x1
    TestJump(0xd4400000, 0x7000, stop, DI_NOT_FOUND, 0);      // hlt #0x0
    TestJump(0x00000000, 0x7000, stop, DI_NOT_FOUND, 0);      // udf #0
}

static void ExpectText(unsigned int word, int options, const char * pExpected);

// instructions objdump 2.42 doesn't know (CMPBR, PAuth_LR, TEV) follow Arm's spec; the address is 0
static void test_arm64_branch_text()
{
    ExpectText(0x540000b1, 0, "bc.ne 0x14");
    ExpectText(0xd61f087f, 0, "braaz x3");
    ExpectText(0xd71f0864, 0, "braa x3, x4");
    ExpectText(0xd71f087f, 0, "braa x3, sp");
    ExpectText(0xd73f0c64, 0, "blrab x3, x4");
    ExpectText(0xd65f0bff, 0, "retaa");
    ExpectText(0xd69f0fff, 0, "eretab");
    ExpectText(0x550000bf, 0, "retaasppc 0xffffffffffffffec");
    ExpectText(0x5520021f, 0, "retabsppc 0xffffffffffffffc0");
    ExpectText(0xd65f0be3, 0, "retaasppcr x3");
    ExpectText(0xd65f0fe3, 0, "retabsppcr x3");
    ExpectText(0xd6ff03e0, 0, "texit");
    ExpectText(0xd6ff07e0, 0, "texit nb");
    ExpectText(0x74020081, 0, "cbgt w1, w2, 0x10");
    ExpectText(0xf4020081, 0, "cbgt x1, x2, 0x10");
    ExpectText(0x741f0081, 0, "cbgt w1, wzr, 0x10");
    ExpectText(0x74c2bfe1, 0, "cbbeq w1, w2, 0xfffffffffffffffc");
    ExpectText(0x7462c081, 0, "cbhhs w1, w2, 0x10");
    ExpectText(0x75018081, 0, "cbgt w1, #0x3, 0x10");
    ExpectText(0xf53f8081, 0, "cblt x1, #0x3f, 0x10");
    ExpectText(0x75600081, 0, "cblo w1, #0x0, 0x10");

    // PAuth_LR data processing, TENTER and SETGO*, objdump 2.42 doesn't know them either
    ExpectText(0xf38000bf, 0, "autiasppc 0xffffffffffffffec");
    ExpectText(0xf3a0021f, 0, "autibsppc 0xffffffffffffffc0");
    ExpectText(0xdac1907e, 0, "autiasppcr x3");
    ExpectText(0xdac1947e, 0, "autibsppcr x3");
    ExpectText(0xdac183fe, 0, "pacnbiasppc");
    ExpectText(0xdac18bfe, 0, "pacia171615");
    ExpectText(0xdac1a3fe, 0, "paciasppc");
    ExpectText(0xdac1bbfe, 0, "autia171615");
    ExpectText(0xd4e00180, 0, "tenter #0xc");
    ExpectText(0xd4e20180, 0, "tenter #0xc, nb");
    ExpectText(0x1ddf0000, 0, ".inst 0x1ddf0000");          // setgop with Rd = Rn
    ExpectText(0x1ddf0020, 0, "setgop [x0]!, x1!");
    ExpectText(0x1ddfb020, 0, "setgoetn [x0]!, x1!");
}

static void test_arm64_profiles()
{
    DianaParserResult result;
    // crc32b w0, w1, w2 needs FEAT_CRC32: Cortex-A72 has it, the v8.0 base doesn't
    DIANA_TEST_ASSERT(DecodeA64(0x1ac24020, &result, DianaArm_FindProfile("rpi4")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "crc32b"));

    DIANA_TEST_ASSERT(DecodeA64(0x1ac24020, &result, DianaArm_FindProfile("armv8.0")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4);

    // a disabled feature falls back to the generic encoding: cfinv is "msr" without FEAT_FlagM
    DIANA_TEST_ASSERT(DecodeA64(0xd500401f, &result, DianaArm_FindProfile("all")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "cfinv"));
    DIANA_TEST_ASSERT(DecodeA64(0xd500401f, &result, DianaArm_FindProfile("rpi4")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "msr"));

    DIANA_TEST_ASSERT(DianaArm_FindProfile("no such profile") == 0);

    // retaa needs FEAT_PAuth (Apple M1 has it), cbgt needs FEAT_CMPBR (no preset has it yet)
    DIANA_TEST_ASSERT(DecodeA64(0xd65f0bff, &result, DianaArm_FindProfile("apple-m1")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "retaa"));
    DIANA_TEST_ASSERT(DecodeA64(0xd65f0bff, &result, DianaArm_FindProfile("armv8.0")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x74020081, &result, DianaArm_FindProfile("apple-m4")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x74020081, &result, DianaArm_FindProfile("all")) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "cbgt"));

    // the profile list: "all" first, every name is found
    {
        int count = 0;
        const DianaArmProfile * pProfiles = DianaArm_GetProfiles(&count);
        DIANA_TEST_ASSERT(count >= 9 && !strcmp(pProfiles[0].pName, "all"));
        for (int i = 0; i < count; ++i)
        {
            DIANA_TEST_ASSERT(DianaArm_FindProfile(pProfiles[i].pName) == pProfiles + i);
            // the AArch32-only CPUs (rpi1, cortex-a7) have no A64 at all
            DIANA_TEST_ASSERT(!pProfiles[i].features || (pProfiles[i].features & DIANA_A64_FEATURE_A64) != 0);
        }
    }
}

static int WordClass(unsigned int word, const char * pProfile = "all")
{
    DianaParserResult result;
    DIANA_TEST_ASSERT(DecodeA64(word, &result, DianaArm_FindProfile(pProfile)) == DI_SUCCESS);
    return DianaA64_GetWordClass(&result);
}

// why a word is ".inst": the analyzer goes on after unsupported and disabled words and stops at unallocated ones
static void test_arm64_word_classes()
{
    DIANA_TEST_ASSERT(WordClass(0x8b020020) == DIANA_A64_WORD_SUPPORTED);            // add x0, x1, x2
    DIANA_TEST_ASSERT(WordClass(0x00000000) == DIANA_A64_WORD_SUPPORTED);            // udf #0
    DIANA_TEST_ASSERT(WordClass(0xf8200020) == DIANA_A64_WORD_SUPPORTED);            // ldadd x0, x0, [x1]
    // valid, not decoded: SVE addpt z0.d, p0/m, z0.d, z0.d and addpt (CPA, no flag); SME; conditional fault cfltgt
    DIANA_TEST_ASSERT(WordClass(0x04c40000) == DIANA_A64_WORD_UNSUPPORTED);
    DIANA_TEST_ASSERT(WordClass(0x9a002020) == DIANA_A64_WORD_UNSUPPORTED);          // addpt x0, x1, x0
    DIANA_TEST_ASSERT(WordClass(0x80040180) == DIANA_A64_WORD_UNSUPPORTED);          // fmop4a (SME_MOP4, no flag)
    DIANA_TEST_ASSERT(WordClass(0x38209020) == DIANA_A64_WORD_SUPPORTED);            // rcwclr x0, x0, [x1] (THE, M4)
    DIANA_TEST_ASSERT(WordClass(0x76000000) == DIANA_A64_WORD_UNSUPPORTED);          // cfltgt
    // casp with an odd Rs: objdump's undefined, but Arm allocates it (CONSTRAINED UNPREDICTABLE)
    DIANA_TEST_ASSERT(WordClass(0x48217c82) == DIANA_A64_WORD_UNSUPPORTED);
    // in the spec, outside the profile
    DIANA_TEST_ASSERT(WordClass(0x1ac24020, "armv8.0") == DIANA_A64_WORD_DISABLED);  // crc32b
    DIANA_TEST_ASSERT(WordClass(0xd65f0bff, "armv8.0") == DIANA_A64_WORD_DISABLED);  // retaa
    DIANA_TEST_ASSERT(WordClass(0x1ac24020, "rpi4") == DIANA_A64_WORD_SUPPORTED);
    // not instructions
    DIANA_TEST_ASSERT(WordClass(0xffffffff) == DIANA_A64_WORD_UNALLOCATED);
    DIANA_TEST_ASSERT(WordClass(0x00800000) == DIANA_A64_WORD_UNALLOCATED);
    DIANA_TEST_ASSERT(WordClass(0x1200fc00) == DIANA_A64_WORD_UNALLOCATED);          // and w0, w0, <reserved imms>
    DIANA_TEST_ASSERT(WordClass(0x1d000420) == DIANA_A64_WORD_UNALLOCATED);          // cpyp with Rd = Rs (/distinct)

    // all three print as ".inst" and are undefined for old clients
    {
        DianaParserResult result;
        static const unsigned int words[] = {0x04c40000, 0xffffffff};
        for (size_t i = 0; i < sizeof(words)/sizeof(words[0]); ++i)
        {
            DIANA_TEST_ASSERT(DecodeA64(words[i], &result) == DI_SUCCESS);
            DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
            DIANA_TEST_ASSERT(result.iFullCmdSize == 4);
        }
        DIANA_TEST_ASSERT(DecodeA64(0x1ac24020, &result, DianaArm_FindProfile("armv8.0")) == DI_SUCCESS);
        DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    }
    ExpectText(0x04c40000, 0, ".inst 0x04c40000");
    ExpectText(0xffffffff, 0, ".inst 0xffffffff");

    // not an AArch64 result
    {
        DianaParserResult result;
        memset(&result, 0, sizeof(result));
        DIANA_TEST_ASSERT(DianaA64_GetWordClass(&result) == -1);
    }
}

static void test_arm64_misc()
{
    DianaParserResult result;

    // group ids are in the ARM range and resolve through Diana_GetGroupInfo
    DIANA_TEST_ASSERT(DecodeA64(0x8b020020, &result) == DI_SUCCESS);    // add x0, x1, x2
    DIANA_TEST_ASSERT(result.pInfo->m_pGroupInfo->m_commandId == (DianaCommandId)diana_a64_cmd_add);
    DIANA_TEST_ASSERT(Diana_GetGroupInfo(diana_a64_cmd_add) == result.pInfo->m_pGroupInfo);
    DIANA_TEST_ASSERT(DIANA_CMD_SET(result.pInfo->m_pGroupInfo->m_commandId) == DIANA_CMD_SET_A64);
    DIANA_TEST_ASSERT(DIANA_CMD_SET(diana_cmd_call) == DIANA_CMD_SET_X86);
    DIANA_TEST_ASSERT(diana_a64_cmd_end < DIANA_A32_CMD_BASE);
    DIANA_TEST_ASSERT(Diana_GetGroupInfo(DIANA_A32_CMD_BASE) != 0);     // the AArch32 ".inst" (M6)
    DIANA_TEST_ASSERT(Diana_GetGroupInfo(diana_a64_cmd_end) == 0);
    DIANA_TEST_ASSERT(DianaA64_GetCmdInfo(&result) != 0);
    DIANA_TEST_ASSERT(result.pInfo->m_operandCount == DianaA64_GetCmdInfo(&result)->operandCount);
    DIANA_TEST_ASSERT(result.bytesCount == 4 && result.bytes[0] == 0x20 && result.bytes[3] == 0x8b);

    // undefined words decode as ".inst" so printers can go on
    DIANA_TEST_ASSERT(DecodeA64(0xffffffff, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));

    // a reserved bitmask immediate is undefined
    DIANA_TEST_ASSERT(DecodeA64(0x1200fc00, &result) == DI_SUCCESS);    // and w0, w0, <imms = 111111>
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));

    // not enough bytes
    {
        unsigned char bytes[2] = {0x1f, 0x20};
        DianaMemoryStream stream;
        DianaContext context;
        Diana_InitContextEx(&context, DIANA_MODE64, DIANA_ARCH_AARCH64);
        Diana_InitMemoryStream(&stream, bytes, sizeof(bytes));
        DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) != DI_SUCCESS);
        Diana_InitMemoryStream(&stream, bytes, 0);
        DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) != DI_SUCCESS);
    }

    // the same word in an AArch32 context is an A32 instruction (test_arm32.cpp)
    {
        DianaContext context;
        Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_ARM32);
        DIANA_TEST_ASSERT(DecodeWord(&context, 0xe1a00000, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(DianaA64_GetCmdInfo(&result) == 0);
    }

    // x86 is the default: the same bytes are x86 code
    {
        DianaContext context;
        Diana_InitContext(&context, DIANA_MODE64);
        DIANA_TEST_ASSERT(context.iArch == DIANA_ARCH_X86);
        DIANA_TEST_ASSERT(DecodeWord(&context, 0x90909090, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(result.iFullCmdSize == 1);
    }

    // DecodeBitMasks
    {
        DI_UINT64 value = 0;
        DIANA_TEST_ASSERT(DianaA64_DecodeBitMasks(0, 0x07, 0, 32, &value) && value == 0xff);
        DIANA_TEST_ASSERT(DianaA64_DecodeBitMasks(1, 0x00, 1, 64, &value) && value == 0x8000000000000000ULL);
        DIANA_TEST_ASSERT(DianaA64_DecodeBitMasks(0, 0x3c, 0, 64, &value) && value == 0x5555555555555555ULL);
        DIANA_TEST_ASSERT(!DianaA64_DecodeBitMasks(0, 0x3f, 0, 32, &value));
    }
}

// the layout and the values clients see: a change here breaks binary compatibility
static void test_arm64_abi()
{
    DIANA_TEST_ASSERT(sizeof(DianaArmOperandExt) == 12);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, opKind) == 0);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, shiftType) == 1);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, shiftAmount) == 2);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, hasAmount) == 3);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, writeback) == 4);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, cond) == 5);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, arrangement) == 6);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, lane) == 7);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, regCount) == 8);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, qualifier) == 9);
    DIANA_TEST_ASSERT(offsetof(DianaLinkedOperand, arm) + sizeof(DianaArmOperandExt) <= sizeof(DianaLinkedOperand));

    DIANA_TEST_ASSERT(diana_arm_shifted_reg == 8);
    DIANA_TEST_ASSERT(diana_arm_cond == 9);
    DIANA_TEST_ASSERT(diana_arm_sysreg == 10);
    DIANA_TEST_ASSERT(diana_arm_special == 11);
    DIANA_TEST_ASSERT(diana_arm_reglist == 12);

    DIANA_TEST_ASSERT(reg_A64_B0 == 0x480 && reg_A64_H0 == 0x4A0 && reg_A64_S0 == 0x4C0);
    DIANA_TEST_ASSERT(reg_A64_D0 == 0x4E0 && reg_A64_Q0 == 0x500 && reg_A64_V0 == 0x520);
    DIANA_TEST_ASSERT(reg_A64_Z0 == 0x540 && reg_A64_P0 == 0x560 && reg_A64_PN0 == 0x570);
    DIANA_TEST_ASSERT(reg_A64_ZA == 0x580 && reg_A64_ZA0 == 0x590 && reg_A64_ZT0 == 0x5A0 && reg_A64_last == 0x5A1);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_SCALABLE(2) == 0x82 && DIANA_ARM_ARR_IS_SCALABLE(0x80) && !DIANA_ARM_ARR_IS_SCALABLE(DIANA_ARM_ARR_S));
    DIANA_TEST_ASSERT(!DIANA_ARM_ARR_HAS_COUNT(DIANA_ARM_ARR_SCALABLE(3)) && DIANA_ARM_ARR_ELEMENT_LOG2(DIANA_ARM_ARR_SCALABLE(3)) == 3);
    DIANA_TEST_ASSERT(DIANA_ARM_QUAL_NONE == 0 && DIANA_ARM_QUAL_MERGE == 1 && DIANA_ARM_QUAL_ZERO == 2);

    // arrangement: element log2 in bits 0..2, log2(count) + 1 in bits 3..5, bit 6 = one element
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_8B == 0x20 && DIANA_ARM_ARR_16B == 0x28);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_2H == 0x11 && DIANA_ARM_ARR_4H == 0x19 && DIANA_ARM_ARR_8H == 0x21);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_2S == 0x12 && DIANA_ARM_ARR_4S == 0x1A);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_1D == 0x0B && DIANA_ARM_ARR_2D == 0x13 && DIANA_ARM_ARR_1Q == 0x0C);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_B == 0x40 && DIANA_ARM_ARR_H == 0x41 && DIANA_ARM_ARR_S == 0x42 && DIANA_ARM_ARR_D == 0x43);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_COUNT(DIANA_ARM_ARR_16B) == 16 && DIANA_ARM_ARR_ELEMENT_LOG2(DIANA_ARM_ARR_16B) == 0);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_COUNT(DIANA_ARM_ARR_1Q) == 1 && DIANA_ARM_ARR_ELEMENT_LOG2(DIANA_ARM_ARR_1Q) == 4);
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_IS_ELEMENT(DIANA_ARM_ARR_S) && !DIANA_ARM_ARR_IS_ELEMENT(DIANA_ARM_ARR_1D));
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_COUNT(DIANA_ARM_ARR_D) == 1 && DIANA_ARM_ARR_ELEMENT_LOG2(DIANA_ARM_ARR_D) == 3);
    // a group of elements indexed as one: v2.4b[1]
    DIANA_TEST_ASSERT(DIANA_ARM_ARR_COUNT(DIANA_ARM_ARR_GROUP(0, 2)) == 4 && DIANA_ARM_ARR_IS_ELEMENT(DIANA_ARM_ARR_GROUP(0, 2)));
    DIANA_TEST_ASSERT(!DIANA_ARM_ARR_HAS_COUNT(DIANA_ARM_ARR_S) && DIANA_ARM_ARR_HAS_COUNT(DIANA_ARM_ARR_GROUP(1, 1)));

    DIANA_TEST_ASSERT(DIANA_A64_OPK_SIMM == 30 && DIANA_A64_OPK_FPREG == 31 && DIANA_A64_OPK_VREG == 32);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_VELEM == 33 && DIANA_A64_OPK_VLIST == 34 && DIANA_A64_OPK_VLIST_ELEM == 35);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_GPREG_IMM5 == 36 && DIANA_A64_OPK_FPIMM == 37 && DIANA_A64_OPK_FZERO == 38);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_MODIMM == 39 && DIANA_A64_OPK_SHIFTIMM == 40 && DIANA_A64_OPK_CONST == 41);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_MEM_POSTIMM == 42 && DIANA_A64_OPK_MEM_POSTREG == 43);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_ROTATE == 44 && DIANA_A64_OPK_MEM_PREIMM == 45);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_ZREG == 46 && DIANA_A64_OPK_PREG == 47);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_SVE_PATTERN == 48 && DIANA_A64_OPK_SVE_IMM8SH == 49 && DIANA_A64_OPK_GPREG_SIZE == 50);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_ZELEM == 51 && DIANA_A64_OPK_ZLIST == 52 && DIANA_A64_OPK_SVE_BIMM == 53);
    DIANA_TEST_ASSERT(DIANA_ARM_SHIFT_MUL == 6 && DIANA_A64_OPK_SVE_FPCONST == 54);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_SVE_MEM_IMM == 55 && DIANA_A64_OPK_SVE_MEM_REG == 56);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_SVE_MEM_ZIMM == 57 && DIANA_A64_OPK_SVE_PRFOP == 58 && DIANA_ARM_SHIFT_MUL_VL == 7);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_PREG_INDEX == 59 && DIANA_A64_OPK_SVE_VLX == 60 && DIANA_A64_SHIFT_RIGHT16 == 3);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_ZA_TILE == 61 && DIANA_A64_OPK_ZA_SLICE == 62 && DIANA_A64_OPK_ZA_MASK == 63);
    DIANA_TEST_ASSERT(DIANA_ARM_QUAL_HORIZONTAL == 3 && DIANA_ARM_QUAL_VERTICAL == 4);
    DIANA_TEST_ASSERT(DIANA_A64_OPK_ZT0 == 64 && DIANA_A64_SHIFT_RIGHT_WIDE == 4);
    DIANA_TEST_ASSERT(offsetof(DianaArmOperandExt, regStride) == 10);
    DIANA_TEST_ASSERT(DIANA_A64_CMDF_SUFFIX2 == 1);
}

static const DianaLinkedOperand * Op(const DianaParserResult * pResult, int index)
{
    return pResult->linkedOperands + index;
}

static void ExpectVector(const DianaLinkedOperand * pOp, int number, int arrangement, int kind)
{
    DIANA_TEST_ASSERT(pOp->type == diana_register);
    DIANA_TEST_ASSERT(pOp->value.recognizedRegister == reg_A64_V0 + number);
    DIANA_TEST_ASSERT(pOp->arm.arrangement == arrangement);
    DIANA_TEST_ASSERT(pOp->arm.opKind == kind);
    DIANA_TEST_ASSERT(pOp->arm.regCount == 0);
}

static void ExpectElement(const DianaLinkedOperand * pOp, int number, int arrangement, int lane)
{
    DIANA_TEST_ASSERT(pOp->type == diana_register);
    DIANA_TEST_ASSERT(pOp->value.recognizedRegister == reg_A64_V0 + number);
    DIANA_TEST_ASSERT(pOp->arm.opKind == DIANA_A64_OPK_VELEM);
    DIANA_TEST_ASSERT(pOp->arm.arrangement == arrangement);
    DIANA_TEST_ASSERT(pOp->arm.lane == lane);
    DIANA_TEST_ASSERT(pOp->usedSize == 1 << DIANA_ARM_ARR_ELEMENT_LOG2(arrangement));
}

static void ExpectList(const DianaLinkedOperand * pOp, int first, int count, int arrangement, int lane)
{
    DIANA_TEST_ASSERT(pOp->type == diana_arm_reglist);
    DIANA_TEST_ASSERT(pOp->value.recognizedRegister == reg_A64_V0 + first);
    DIANA_TEST_ASSERT(pOp->arm.regCount == count);
    DIANA_TEST_ASSERT(pOp->arm.arrangement == arrangement);
    DIANA_TEST_ASSERT(pOp->arm.lane == lane);
}

static void ExpectMemory(const DianaLinkedOperand * pOp, DianaUnifiedRegister base, DianaUnifiedRegister index,
                         long long disp, int writeback)
{
    DIANA_TEST_ASSERT(pOp->type == diana_index);
    DIANA_TEST_ASSERT(pOp->value.rmIndex.reg == base);
    DIANA_TEST_ASSERT(pOp->value.rmIndex.indexed_reg == index);
    DIANA_TEST_ASSERT((long long)pOp->value.rmIndex.dispValue == disp);
    DIANA_TEST_ASSERT(pOp->arm.writeback == writeback);
}

static void ExpectImm(const DianaLinkedOperand * pOp, DI_UINT64 value, int kind)
{
    DIANA_TEST_ASSERT(pOp->type == diana_imm);
    DIANA_TEST_ASSERT(pOp->value.imm == value);
    DIANA_TEST_ASSERT(pOp->arm.opKind == kind);
}

// FP/SIMD operands as clients see them (DianaLinkedOperand), every new operand kind
static void test_arm64_simd_operands()
{
    DianaParserResult result;

    // ld1 {v0.16b-v3.16b}, [x0]
    DIANA_TEST_ASSERT(DecodeA64(0x4c402000, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 2);
    ExpectList(Op(&result, 0), 0, 4, DIANA_ARM_ARR_16B, 0);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.opKind == DIANA_A64_OPK_VLIST);
    DIANA_TEST_ASSERT(Op(&result, 0)->usedSize == 16);
    ExpectMemory(Op(&result, 1), reg_A64_X0, reg_none, 0, DIANA_ARM_WRITEBACK_NONE);

    // ld1 {v31.2d-v0.2d}, [x0]: the list wraps after v31
    DIANA_TEST_ASSERT(DecodeA64(0x4c40ac1f, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 31, 2, DIANA_ARM_ARR_2D, 0);

    // ld1 {v0.16b-v1.16b}, [x0], #32
    DIANA_TEST_ASSERT(DecodeA64(0x4cdfa000, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 0, 2, DIANA_ARM_ARR_16B, 0);
    ExpectMemory(Op(&result, 1), reg_A64_X0, reg_none, 32, DIANA_ARM_WRITEBACK_POST);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.opKind == DIANA_A64_OPK_MEM_POSTIMM);

    // ld1 {v0.8b-v2.8b}, [x0], x2
    DIANA_TEST_ASSERT(DecodeA64(0x0cc26000, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 0, 3, DIANA_ARM_ARR_8B, 0);
    ExpectMemory(Op(&result, 1), reg_A64_X0, (DianaUnifiedRegister)(reg_A64_X0 + 2), 0, DIANA_ARM_WRITEBACK_POST);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.opKind == DIANA_A64_OPK_MEM_POSTREG);

    // ld3r {v0.4h-v2.4h}, [sp], #6
    DIANA_TEST_ASSERT(DecodeA64(0x0ddfe7e0, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 0, 3, DIANA_ARM_ARR_4H, 0);
    ExpectMemory(Op(&result, 1), reg_A64_SP, reg_none, 6, DIANA_ARM_WRITEBACK_POST);

    // st4 {v1.b-v4.b}[15], [x1] and ld1 {v0.s}[1], [x0], #4: element lists
    DIANA_TEST_ASSERT(DecodeA64(0x4d203c21, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 1, 4, DIANA_ARM_ARR_B, 15);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.opKind == DIANA_A64_OPK_VLIST_ELEM);
    DIANA_TEST_ASSERT(DecodeA64(0x0ddf9000, &result) == DI_SUCCESS);
    ExpectList(Op(&result, 0), 0, 1, DIANA_ARM_ARR_S, 1);
    ExpectMemory(Op(&result, 1), reg_A64_X0, reg_none, 4, DIANA_ARM_WRITEBACK_POST);

    // ldr q0, [x0, #16]: a Q register and the access size
    DIANA_TEST_ASSERT(DecodeA64(0x3dc00400, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_register);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_Q0);
    DIANA_TEST_ASSERT(Op(&result, 0)->usedSize == 16);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.opKind == DIANA_A64_OPK_FPREG);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.arrangement == 0);
    ExpectMemory(Op(&result, 1), reg_A64_X0, reg_none, 16, DIANA_ARM_WRITEBACK_NONE);

    // fmov d0, #1.0 and fmov s1, #-0.125: the immediate is the IEEE double
    DIANA_TEST_ASSERT(DecodeA64(0x1e6e1000, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_D0 && Op(&result, 0)->usedSize == 8);
    ExpectImm(Op(&result, 1), 0x3FF0000000000000ULL, DIANA_A64_OPK_FPIMM);
    DIANA_TEST_ASSERT(DecodeA64(0x1e381001, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_S0 + 1 && Op(&result, 0)->usedSize == 4);
    ExpectImm(Op(&result, 1), 0xBFC0000000000000ULL, DIANA_A64_OPK_FPIMM);

    // fmov v0.4s, #31.0
    DIANA_TEST_ASSERT(DecodeA64(0x4f01f7e0, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_4S, DIANA_A64_OPK_VREG);
    ExpectImm(Op(&result, 1), 0x403F000000000000ULL, DIANA_A64_OPK_FPIMM);

    // movi v1.4s, #0x12, lsl #8 / msl #16; movi v0.2d, #0xff00ff00ff00ff00
    DIANA_TEST_ASSERT(DecodeA64(0x4f002641, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 1, DIANA_ARM_ARR_4S, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(Op(&result, 0)->usedSize == 16);
    ExpectImm(Op(&result, 1), 0x12, DIANA_A64_OPK_MODIMM);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.shiftType == DIANA_ARM_SHIFT_LSL && Op(&result, 1)->arm.shiftAmount == 8);
    DIANA_TEST_ASSERT(DecodeA64(0x4f00d641, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 1), 0x12, DIANA_A64_OPK_MODIMM);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.shiftType == DIANA_ARM_SHIFT_MSL && Op(&result, 1)->arm.shiftAmount == 16);
    DIANA_TEST_ASSERT(DecodeA64(0x6f05e540, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_2D, DIANA_A64_OPK_VREG);
    ExpectImm(Op(&result, 1), 0xff00ff00ff00ff00ULL, DIANA_A64_OPK_MODIMM);

    // ins v0.s[1], w1; ins v0.s[1], v2.s[3]; umov x0, v1.d[1]; dup v0.4s, w1
    DIANA_TEST_ASSERT(DecodeA64(0x4e0c1c20, &result) == DI_SUCCESS);
    ExpectElement(Op(&result, 0), 0, DIANA_ARM_ARR_S, 1);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_W0 + 1);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.opKind == DIANA_A64_OPK_GPREG_IMM5 && Op(&result, 1)->usedSize == 4);
    DIANA_TEST_ASSERT(DecodeA64(0x6e0c6440, &result) == DI_SUCCESS);
    ExpectElement(Op(&result, 0), 0, DIANA_ARM_ARR_S, 1);
    ExpectElement(Op(&result, 1), 2, DIANA_ARM_ARR_S, 3);
    DIANA_TEST_ASSERT(DecodeA64(0x4e183c20, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_X0);
    ExpectElement(Op(&result, 1), 1, DIANA_ARM_ARR_D, 1);
    DIANA_TEST_ASSERT(DecodeA64(0x4e040c20, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_4S, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_W0 + 1);

    // by element: mla v0.8h, v1.8h, v15.h[7] (v0-v15, H:L:M); fmla v0.2d, v1.2d, v31.d[1] (M:Rm, H)
    DIANA_TEST_ASSERT(DecodeA64(0x6f7f0820, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_8H, DIANA_A64_OPK_VREG);
    ExpectElement(Op(&result, 2), 15, DIANA_ARM_ARR_H, 7);
    DIANA_TEST_ASSERT(DecodeA64(0x4fdf1820, &result) == DI_SUCCESS);
    ExpectElement(Op(&result, 2), 31, DIANA_ARM_ARR_D, 1);
    DIANA_TEST_ASSERT(DecodeA64(0x4fa21820, &result) == DI_SUCCESS);    // fmla v0.4s, v1.4s, v2.s[3]
    ExpectElement(Op(&result, 2), 2, DIANA_ARM_ARR_S, 3);

    // fmov x0, v1.d[1]: an element with a fixed index
    DIANA_TEST_ASSERT(DecodeA64(0x9eae0020, &result) == DI_SUCCESS);
    ExpectElement(Op(&result, 1), 1, DIANA_ARM_ARR_D, 1);

    // shifts: sshr v0.2d, v1.2d, #64; shl d0, d1, #63; scvtf s0, w1, #32 (fbits)
    DIANA_TEST_ASSERT(DecodeA64(0x4f400420, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_2D, DIANA_A64_OPK_VREG);
    ExpectImm(Op(&result, 2), 64, DIANA_A64_OPK_SHIFTIMM);
    DIANA_TEST_ASSERT(DecodeA64(0x5f7f5420, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_D0);
    ExpectImm(Op(&result, 2), 63, DIANA_A64_OPK_SHIFTIMM);
    DIANA_TEST_ASSERT(DecodeA64(0x1e028020, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 2), 32, DIANA_A64_OPK_SHIFTIMM);

    // fcmeq v0.4s, v1.4s, #0.0; cmeq v0.16b, v1.16b, #0; shll v0.8h, v1.8b, #8
    DIANA_TEST_ASSERT(DecodeA64(0x4ea0d820, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 2), 0, DIANA_A64_OPK_FZERO);
    DIANA_TEST_ASSERT(DecodeA64(0x4e209820, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 2), 0, DIANA_A64_OPK_CONST);
    DIANA_TEST_ASSERT(DecodeA64(0x2e213820, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_8H, DIANA_A64_OPK_VREG);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_8B, DIANA_A64_OPK_VREG);
    ExpectImm(Op(&result, 2), 8, DIANA_A64_OPK_CONST);

    // arrangements: faddp s0, v1.2s; faddp h0, v1.2h; pmull v0.1q, v1.1d, v2.1d; fcvtl2 v0.2d, v1.4s
    DIANA_TEST_ASSERT(DecodeA64(0x7e30d820, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_2S, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(DecodeA64(0x5e30d820, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_H0);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_2H, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(Op(&result, 1)->usedSize == 4);
    DIANA_TEST_ASSERT(DecodeA64(0x0ee2e020, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_1Q, DIANA_A64_OPK_VREG);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_1D, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(Op(&result, 1)->usedSize == 8);
    DIANA_TEST_ASSERT(DecodeA64(0x4e617820, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_2D, DIANA_A64_OPK_VREG);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_4S, DIANA_A64_OPK_VREG);

    // the upper half forms: one group, DIANA_A64_CMDF_SUFFIX2, Q tells which (shrn2 v0.16b, v1.8h, #8 / fcvtn v0.4h, v0.4s)
    DIANA_TEST_ASSERT(DecodeA64(0x4f088420, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "shrn"));
    DIANA_TEST_ASSERT(DianaA64_GetCmdInfo(&result)->flags & DIANA_A64_CMDF_SUFFIX2);
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_16B, DIANA_A64_OPK_VREG);
    ExpectVector(Op(&result, 1), 1, DIANA_ARM_ARR_8H, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(DecodeA64(0x0e216800, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "fcvtn"));
    ExpectVector(Op(&result, 0), 0, DIANA_ARM_ARR_4H, DIANA_A64_OPK_VREG);
    DIANA_TEST_ASSERT(DecodeA64(0x4e617820, &result) == DI_SUCCESS);    // fcvtl2: the same group as fcvtl
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "fcvtl"));

    // reserved: add with 1D (size 11, Q 0) and dup with imm5 x0000 are undefined
    DIANA_TEST_ASSERT(DecodeA64(0x0ee08400, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x4e000c20, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
}

static void ExpectText(unsigned int word, int options, const char * pExpected)
{
    diana::CMasmString text;
    text.SetOptions(options);
    DianaParserResult result;
    DIANA_TEST_ASSERT(DecodeA64(word, &result) == DI_SUCCESS);
    const char * pText = text.Assign(&result, 0);
    if (strcmp(pText, pExpected) != 0)
    {
        printf("arm64: %08x: expected \"%s\", got \"%s\"\n", word, pExpected, pText);
        DIANA_TEST_ASSERT(0);
    }
}

// SIMD aliases, raw forms and print formats that random words rarely hit; the text is objdump's
static void test_arm64_simd_text()
{
    const int raw = DIANA_TEXT_OUTPUT_OPTION_ARM_NO_ALIASES;
    ExpectText(0x4ea11c20, 0, "mov v0.16b, v1.16b");
    ExpectText(0x4ea11c20, raw, "orr v0.16b, v1.16b, v1.16b");
    ExpectText(0x4ea21c20, 0, "orr v0.16b, v1.16b, v2.16b");
    ExpectText(0x0f08a420, 0, "sxtl v0.8h, v1.8b");
    ExpectText(0x0f08a420, raw, "sshll v0.8h, v1.8b, #0");
    ExpectText(0x6f20a420, 0, "uxtl2 v0.2d, v1.4s");
    ExpectText(0x6f20a420, raw, "ushll2 v0.2d, v1.4s, #0");
    ExpectText(0x6f23a420, 0, "ushll2 v0.2d, v1.4s, #3");
    ExpectText(0x6e205820, 0, "mvn v0.16b, v1.16b");
    ExpectText(0x6e205820, raw, "not v0.16b, v1.16b");
    ExpectText(0x4e0c1c20, 0, "mov v0.s[1], w1");
    ExpectText(0x4e0c1c20, raw, "ins v0.s[1], w1");
    ExpectText(0x6e0c6440, 0, "mov v0.s[1], v2.s[3]");
    ExpectText(0x4e183c20, 0, "mov x0, v1.d[1]");
    ExpectText(0x4e183c20, raw, "umov x0, v1.d[1]");
    ExpectText(0x0e0e3c20, 0, "umov w0, v1.h[3]");
    ExpectText(0x5e070420, 0, "mov b0, v1.b[3]");
    ExpectText(0x5e070420, raw, "dup b0, v1.b[3]");
    ExpectText(0x4e1e0420, 0, "dup v0.8h, v1.h[7]");
    ExpectText(0x4e040c20, 0, "dup v0.4s, w1");

    ExpectText(0x1e6e1000, 0, "fmov d0, #1.000000000000000000e+00");
    ExpectText(0x1e381001, 0, "fmov s1, #-1.250000000000000000e-01");
    ExpectText(0x4f01f7e0, 0, "fmov v0.4s, #3.100000000000000000e+01");
    ExpectText(0x4f002641, 0, "movi v1.4s, #0x12, lsl #8");
    ExpectText(0x4f00d641, 0, "movi v1.4s, #0x12, msl #16");
    ExpectText(0x6f05e540, 0, "movi v0.2d, #0xff00ff00ff00ff00");
    ExpectText(0x2f00e420, 0, "movi d0, #0xff");
    ExpectText(0x4c402000, 0, "ld1 {v0.16b-v3.16b}, [x0]");
    ExpectText(0x4c40ac1f, 0, "ld1 {v31.2d-v0.2d}, [x0]");
    ExpectText(0x0cc26000, 0, "ld1 {v0.8b-v2.8b}, [x0], x2");
    ExpectText(0x4d203c21, 0, "st4 {v1.b-v4.b}[15], [x1]");
    ExpectText(0x0ee2e020, 0, "pmull v0.1q, v1.1d, v2.1d");
    ExpectText(0x4e22e020, 0, "pmull2 v0.8h, v1.16b, v2.16b");
    ExpectText(0x6e021820, 0, "ext v0.16b, v1.16b, v2.16b, #3");
    ExpectText(0x0e0253c0, 0, "tbx v0.8b, {v30.16b-v0.16b}, v2.8b");
    ExpectText(0x5e30d820, 0, "faddp h0, v1.2h");
    ExpectText(0x4fdf1820, 0, "fmla v0.2d, v1.2d, v31.d[1]");
}

// FP16, AES and SHA are not ARMv8.0: the profile hides them, advanced SIMD itself is there
static void test_arm64_simd_profiles()
{
    static const unsigned int optional[] = {0x4e284820 /* aese */, 0x5e024020 /* sha256h */,
                                            0x5e020020 /* sha1c */, 0x1ee00800 /* fmul h0 */, 0x0e400c00 /* fmla .4h */};
    const DianaArmProfile * pV80 = DianaArm_FindProfile("armv8.0");
    const DianaArmProfile * pRpi5 = DianaArm_FindProfile("rpi5");
    DianaParserResult result;
    for (size_t i = 0; i < sizeof(optional)/sizeof(optional[0]); ++i)
    {
        DIANA_TEST_ASSERT(DecodeA64(optional[i], &result, pV80) == DI_SUCCESS);
        DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
        DIANA_TEST_ASSERT(DecodeA64(optional[i], &result, pRpi5) == DI_SUCCESS);
        DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    }
    DIANA_TEST_ASSERT(DecodeA64(0x4ea11c20, &result, pV80) == DI_SUCCESS);    // orr v0.16b
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x1e6e1000, &result, pV80) == DI_SUCCESS);    // fmov d0, #1.0
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
}

// M5: Z and P registers as clients see them
static void ExpectScalable(const DianaLinkedOperand * pOp, DianaUnifiedRegister reg, int arrangement, int qualifier, int kind)
{
    DIANA_TEST_ASSERT(pOp->type == diana_register);
    DIANA_TEST_ASSERT(pOp->value.recognizedRegister == reg);
    DIANA_TEST_ASSERT(pOp->arm.arrangement == arrangement);
    DIANA_TEST_ASSERT(pOp->arm.qualifier == qualifier);
    DIANA_TEST_ASSERT(pOp->arm.opKind == kind);
}

static void test_arm64_sve_operands()
{
    DianaParserResult result;

    // add z10.s, p6/m, z10.s, z2.s
    DIANA_TEST_ASSERT(DecodeA64(0x0480184a, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 4);
    ExpectScalable(Op(&result, 0), (DianaUnifiedRegister)(reg_A64_Z0 + 10), DIANA_ARM_ARR_SCALABLE(2), 0, DIANA_A64_OPK_ZREG);
    ExpectScalable(Op(&result, 1), (DianaUnifiedRegister)(reg_A64_P0 + 6), 0, DIANA_ARM_QUAL_MERGE, DIANA_A64_OPK_PREG);
    ExpectScalable(Op(&result, 3), (DianaUnifiedRegister)(reg_A64_Z0 + 2), DIANA_ARM_ARR_SCALABLE(2), 0, DIANA_A64_OPK_ZREG);
    // add z0.b, z1.b, z31.b, and the D form
    DIANA_TEST_ASSERT(DecodeA64(0x043f0020, &result) == DI_SUCCESS);
    ExpectScalable(Op(&result, 0), reg_A64_Z0, DIANA_ARM_ARR_SCALABLE(0), 0, DIANA_A64_OPK_ZREG);
    ExpectScalable(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_Z0 + 31), DIANA_ARM_ARR_SCALABLE(0), 0, DIANA_A64_OPK_ZREG);
    DIANA_TEST_ASSERT(DecodeA64(0x04ff0020, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(3));
    // sdiv: only S and D (size 1x); size 0x is reserved
    DIANA_TEST_ASSERT(DecodeA64(0x04941c00, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x04541c00, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));

    // step 2 kinds. cntb x0, all, mul #2: the pattern and its multiplier
    DIANA_TEST_ASSERT(DecodeA64(0x0421e3e0, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->type == diana_arm_special && Op(&result, 1)->value.imm == 31);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.shiftType == DIANA_ARM_SHIFT_MUL && Op(&result, 1)->arm.shiftAmount == 2);
    // ptrue p2.b: no multiplier field is mul #1, the "all" pattern is not printed
    DIANA_TEST_ASSERT(DecodeA64(0x2518e3e2, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 2 && Op(&result, 1)->value.imm == 31 && Op(&result, 1)->arm.shiftAmount == 1);
    // cpy z23.s, p5/z, #-15616: imm8 = -61, lsl #8 folded into the value
    DIANA_TEST_ASSERT(DecodeA64(0x05953877, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 2), (DI_UINT64)-15616, DIANA_A64_OPK_SVE_IMM8SH);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.shiftType == DIANA_ARM_SHIFT_LSL && Op(&result, 2)->arm.shiftAmount == 8);
    // index z31.d, x29, #10: x by size 11; index z6.h, #3, w15: w otherwise
    DIANA_TEST_ASSERT(DecodeA64(0x04ea47bf, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_X0 + 29 && Op(&result, 1)->usedSize == 8);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.opKind == DIANA_A64_OPK_GPREG_SIZE);
    DIANA_TEST_ASSERT(DecodeA64(0x046f4866, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 2)->value.recognizedRegister == reg_A64_W0 + 15 && Op(&result, 2)->usedSize == 4);
    // sdot z11.s, z19.b, z0.b[3]; dup z26.h, z9.h[10] (index imm2:tsz >> 2)
    DIANA_TEST_ASSERT(DecodeA64(0x44b8026b, &result) == DI_SUCCESS);
    ExpectScalable(Op(&result, 2), reg_A64_Z0, DIANA_ARM_ARR_SCALABLE(0) | 0x40, 0, DIANA_A64_OPK_ZELEM);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.lane == 3);
    DIANA_TEST_ASSERT(DecodeA64(0x056a213a, &result) == DI_SUCCESS);
    ExpectScalable(Op(&result, 1), (DianaUnifiedRegister)(reg_A64_Z0 + 9), DIANA_ARM_ARR_SCALABLE(1) | 0x40, 0, DIANA_A64_OPK_ZELEM);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.lane == 10);
    // tbl z28.b, {z9.b}, z15.b
    DIANA_TEST_ASSERT(DecodeA64(0x052f313c, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->type == diana_arm_reglist && Op(&result, 1)->value.recognizedRegister == reg_A64_Z0 + 9);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.regCount == 1 && Op(&result, 1)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(0));
    // and z14.b, z14.b, #0x77: a 4-bit pattern is a byte element
    DIANA_TEST_ASSERT(DecodeA64(0x0580c74e, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(0));
    ExpectImm(Op(&result, 2), 0x77, DIANA_A64_OPK_SVE_BIMM);
    // movprfx z22.s, p4/z and p1/m: the qualifier from the M field
    DIANA_TEST_ASSERT(DecodeA64(0x04903396, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.qualifier == DIANA_ARM_QUAL_ZERO);
    DIANA_TEST_ASSERT(DecodeA64(0x04512584, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.qualifier == DIANA_ARM_QUAL_MERGE);
    // smaxv d25, p0, z4.d: a scalar register in the Vd field
    DIANA_TEST_ASSERT(DecodeA64(0x04c82099, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->value.recognizedRegister == reg_A64_D0 + 25);

    // step 3: fadd z25.d, p0/m, z25.d, #0.5; fmul ..., #2.0; fmax ..., #0.0: the constant as an IEEE double
    DIANA_TEST_ASSERT(DecodeA64(0x65d88019, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 3), 0x3FE0000000000000ULL, DIANA_A64_OPK_SVE_FPCONST);
    DIANA_TEST_ASSERT(DecodeA64(0x659a883b, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 3), 0x4000000000000000ULL, DIANA_A64_OPK_SVE_FPCONST);
    DIANA_TEST_ASSERT(DecodeA64(0x655e980e, &result) == DI_SUCCESS);
    ExpectImm(Op(&result, 3), 0, DIANA_A64_OPK_SVE_FPCONST);

    // step 4: ld2b {z28.b-z29.b}, p1/z, [x9, #-2, mul vl]: two registers, the offset in vector lengths (imm4 * 2)
    DIANA_TEST_ASSERT(DecodeA64(0xa42fe53c, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_arm_reglist && Op(&result, 0)->arm.regCount == 2);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_X0 + 9), reg_none, -2, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.shiftType == DIANA_ARM_SHIFT_MUL_VL && Op(&result, 2)->arm.opKind == DIANA_A64_OPK_SVE_MEM_IMM);
    // ld1rob {z25.b}, p4/z, [x28, #-160]: bytes, imm4 * 32
    DIANA_TEST_ASSERT(DecodeA64(0xa42b3399, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_X0 + 28), reg_none, -160, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.shiftType == DIANA_ARM_SHIFT_NONE);
    // ldff1b {z9.b}, p1/z, [x0, xzr]; ld2d ..., [x23, x6, lsl #3]
    DIANA_TEST_ASSERT(DecodeA64(0xa41f6409, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), reg_A64_X0, reg_A64_XZR, 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(DecodeA64(0xa5a6c2ea, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_X0 + 23), (DianaUnifiedRegister)(reg_A64_X0 + 6), 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.shiftType == DIANA_ARM_SHIFT_LSL && Op(&result, 2)->arm.shiftAmount == 3);
    // ld1d {z29.d}, p2/z, [x26, z13.d, uxtw #3]: a Z index, extended by the xs field
    DIANA_TEST_ASSERT(DecodeA64(0xc5ad4b5d, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_X0 + 26), (DianaUnifiedRegister)(reg_A64_Z0 + 13), 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.shiftType == DIANA_ARM_EXTEND_UXTW && Op(&result, 2)->arm.shiftAmount == 3);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(3) && Op(&result, 2)->arm.hasAmount);
    // ld1b {z23.d}, p3/z, [z10.d, #20]: a Z base
    DIANA_TEST_ASSERT(DecodeA64(0xc434cd57, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_Z0 + 10), reg_none, 20, DIANA_ARM_WRITEBACK_NONE);
    // adr z23.d, [z17.d, z17.d, sxtw #3]: the shift from msz
    DIANA_TEST_ASSERT(DecodeA64(0x0431ae37, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 1), (DianaUnifiedRegister)(reg_A64_Z0 + 17), (DianaUnifiedRegister)(reg_A64_Z0 + 17), 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.shiftType == DIANA_ARM_EXTEND_SXTW && Op(&result, 1)->arm.shiftAmount == 3);
    // prfb pldl3keep: the prefetch operation
    DIANA_TEST_ASSERT(DecodeA64(0xc41feae4, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_arm_special && Op(&result, 0)->value.imm == 4);

    // step 5: ptrue pn15.s (a 3-bit field: pn8..pn15); cntp x5, pn10.d, vlx4 (4 bits)
    DIANA_TEST_ASSERT(DecodeA64(0x25a07817, &result) == DI_SUCCESS);
    ExpectScalable(Op(&result, 0), (DianaUnifiedRegister)(reg_A64_PN0 + 15), DIANA_ARM_ARR_SCALABLE(2), 0, DIANA_A64_OPK_PREG);
    DIANA_TEST_ASSERT(DecodeA64(0x25e08745, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_PN0 + 10);
    DIANA_TEST_ASSERT(Op(&result, 2)->type == diana_arm_special && Op(&result, 2)->value.imm == 4);
    // pext p1.s, pn13[2]: an index on a PN register; pext {p6.h-p7.h}, pn11[0]: an even pair
    DIANA_TEST_ASSERT(DecodeA64(0x25a072b1, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_PN0 + 13 && Op(&result, 1)->arm.lane == 2);
    DIANA_TEST_ASSERT(DecodeA64(0x25607476, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_arm_reglist && Op(&result, 0)->value.recognizedRegister == reg_A64_P0 + 6);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.regCount == 2);
    // psel p15, p8, p13.h[w14, 6]
    DIANA_TEST_ASSERT(DecodeA64(0x25ea61af, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_P0 + 13), (DianaUnifiedRegister)(reg_A64_W0 + 14), 6, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(1) && Op(&result, 2)->arm.opKind == DIANA_A64_OPK_PREG_INDEX);
    // addqv v18.16b, p2, z31.b: a 128-bit vector in the Vd field
    DIANA_TEST_ASSERT(DecodeA64(0x04052bf2, &result) == DI_SUCCESS);
    ExpectVector(Op(&result, 0), 18, DIANA_ARM_ARR_16B, DIANA_A64_OPK_VREG);
    // sqcvtn z28.h, {z8.s-z9.s}: a 4-bit field counts pairs
    DIANA_TEST_ASSERT(DecodeA64(0x4531411c, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_Z0 + 8 && Op(&result, 1)->arm.regCount == 2);
    // ldnt1sh {z25.s}, p2/z, [z6.s, xzr]
    DIANA_TEST_ASSERT(DecodeA64(0x849f88d9, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_Z0 + 6), reg_A64_XZR, 0, DIANA_ARM_WRITEBACK_NONE);

    // step 6 (SME): fmopa za4.d, p3/m, p1/m, z15.d, z9.d: a tile
    DIANA_TEST_ASSERT(DecodeA64(0x80c92de4, &result) == DI_SUCCESS);
    ExpectScalable(Op(&result, 0), (DianaUnifiedRegister)(reg_A64_ZA0 + 4), DIANA_ARM_ARR_SCALABLE(3), 0, DIANA_A64_OPK_ZA_TILE);
    // mov za0v.b[w15, 6], p1/m, z0.b: a vertical slice of za0
    DIANA_TEST_ASSERT(DecodeA64(0xc000e406, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 0), reg_A64_ZA0, (DianaUnifiedRegister)(reg_A64_W0 + 15), 6, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.qualifier == DIANA_ARM_QUAL_VERTICAL && Op(&result, 0)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(0));
    // mov z14.q, p7/m, za8h.q[w15, 0]: Q tiles have no offset field
    DIANA_TEST_ASSERT(DecodeA64(0xc0c37d0e, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 2), (DianaUnifiedRegister)(reg_A64_ZA0 + 8), (DianaUnifiedRegister)(reg_A64_W0 + 15), 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 2)->arm.qualifier == DIANA_ARM_QUAL_HORIZONTAL);
    // ldr za[w12, 12], [x17, #12, mul vl]: the array, the offset is unsigned
    DIANA_TEST_ASSERT(DecodeA64(0xe100022c, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 0), reg_A64_ZA, (DianaUnifiedRegister)(reg_A64_W0 + 12), 12, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.arrangement == 0 && Op(&result, 0)->arm.qualifier == 0);
    ExpectMemory(Op(&result, 1), (DianaUnifiedRegister)(reg_A64_X0 + 17), reg_none, 12, DIANA_ARM_WRITEBACK_NONE);
    // zero {za0.s, za2.d, za5.d, za7.d}: the mask
    DIANA_TEST_ASSERT(DecodeA64(0xc00800b5, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_arm_special && Op(&result, 0)->value.imm == 0xb5);
    ExpectText(0xc000e406, DIANA_TEXT_OUTPUT_OPTION_ARM_NO_ALIASES, "mov za0v.b[w15, 6], p1/m, z0.b");

    // step 7 (SME2): bfmlal za.s[w8, 6:7, vgx2], ...: a vector group, two slices from offset 3 * 2
    DIANA_TEST_ASSERT(DecodeA64(0xc1911dd7, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 0), reg_A64_ZA, (DianaUnifiedRegister)(reg_A64_W0 + 8), 6, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.lane == 1 && Op(&result, 0)->arm.regCount == 2);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.arrangement == DIANA_ARM_ARR_SCALABLE(2));
    // ld1b {z17.b, z21.b, z25.b, z29.b}: strided by 4
    DIANA_TEST_ASSERT(DecodeA64(0xa11c82b1, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 0)->type == diana_arm_reglist && Op(&result, 0)->value.recognizedRegister == reg_A64_Z0 + 17);
    DIANA_TEST_ASSERT(Op(&result, 0)->arm.regCount == 4 && Op(&result, 0)->arm.regStride == 4);
    // mov {z4.d-z5.d}, za6h.d[w12, 0:1]: a range of tile slices
    DIANA_TEST_ASSERT(DecodeA64(0xc0c600c4, &result) == DI_SUCCESS);
    ExpectMemory(Op(&result, 1), (DianaUnifiedRegister)(reg_A64_ZA0 + 6), (DianaUnifiedRegister)(reg_A64_W0 + 12), 0, DIANA_ARM_WRITEBACK_NONE);
    DIANA_TEST_ASSERT(Op(&result, 1)->arm.lane == 1 && Op(&result, 1)->arm.regCount == 0);
    // luti2 {z0.h-z1.h}, zt0, z4[0]; movt x14, zt0[56]
    DIANA_TEST_ASSERT(DecodeA64(0xc08c5080, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->type == diana_register && Op(&result, 1)->value.recognizedRegister == reg_A64_ZT0);
    DIANA_TEST_ASSERT(Op(&result, 2)->value.recognizedRegister == reg_A64_Z0 + 4 && Op(&result, 2)->arm.arrangement == 0x40);
    DIANA_TEST_ASSERT(DecodeA64(0xc04c73ee, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 1)->value.recognizedRegister == reg_A64_ZT0 && Op(&result, 1)->arm.lane == 56);
    // sqrshr z25.h, {z4.d-z7.d}, #27: 128 - tsize:imm5
    DIANA_TEST_ASSERT(DecodeA64(0xc1e5d899, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(Op(&result, 2)->value.imm == 27);

    ExpectText(0x0480184a, 0, "add z10.s, p6/m, z10.s, z2.s");
    ExpectText(0x04d40fff, 0, "sdiv z31.d, p3/m, z31.d, z31.d");
    ExpectText(0x04a00400, 0, "sub z0.s, z0.s, z0.s");
}

// "sve|sme" lines: decoded with SVE or with SME (Apple M4 has SME without SVE), hidden without both
static void test_arm64_sve_profiles()
{
    DianaArmProfile sveOnly = {"sve", "", DIANA_A64_FEATURE_A64|DIANA_A64_FEATURE_SVE};
    DianaArmProfile smeOnly = {"sme", "", DIANA_A64_FEATURE_A64|DIANA_A64_FEATURE_SME};
    DianaArmProfile neither = {"base", "", DIANA_A64_FEATURE_A64|DIANA_A64_FEATURE_SVE2|DIANA_A64_FEATURE_SME2};
    DianaParserResult result;
    DIANA_TEST_ASSERT(DecodeA64(0x0480184a, &result, &sveOnly) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x0480184a, &result, &smeOnly) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DecodeA64(0x0480184a, &result, &neither) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result));
    DIANA_TEST_ASSERT(DianaA64_GetWordClass(&result) == DIANA_A64_WORD_DISABLED);
    // the generated command: no required feature, any of SVE and SME
    {
        const DianaA64CmdInfo * pCmd = 0;
        DIANA_TEST_ASSERT(DecodeA64(0x0480184a, &result) == DI_SUCCESS);
        pCmd = DianaA64_GetCmdInfo(&result);
        DIANA_TEST_ASSERT(pCmd && pCmd->features == 0);
        DIANA_TEST_ASSERT(pCmd && pCmd->featuresAny != 0);
        DIANA_TEST_ASSERT(pCmd && DianaA64_GetTables()->pFeaturesAny[pCmd->featuresAny] == (DIANA_A64_FEATURE_SVE|DIANA_A64_FEATURE_SME));
        DIANA_TEST_ASSERT(DianaA64_GetTables()->pFeaturesAny[0] == 0);
        DIANA_TEST_ASSERT(pCmd && DianaA64_IsCmdEnabled(pCmd, smeOnly.features) && !DianaA64_IsCmdEnabled(pCmd, neither.features));
        // featuresAny is an index in what was padding: the struct keeps its M4 size on 64-bit builds
        DIANA_TEST_ASSERT(sizeof(void *) != 8 || sizeof(DianaA64CmdInfo) == 176);
    }
}

// SME2: the .d forms of a few multi-vector instructions also need I16I64 (Arm: sz == 0 || FEAT_SME_I16I64), a line per sz
static void test_arm64_sme2_profiles()
{
    DianaArmProfile sme2 = {"sme2", "", DIANA_A64_FEATURE_A64|DIANA_A64_FEATURE_SME|DIANA_A64_FEATURE_SME2};
    DianaArmProfile i16i64 = {"i16i64", "", sme2.features|DIANA_A64_FEATURE_SME_I16I64};
    DianaParserResult result;
    // smlall za.s[w11, 0:3, vgx2], {z14.b-z15.b}, z1.b: SME2 only
    DIANA_TEST_ASSERT(DecodeA64(0xc12161c0, &result, &sme2) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
    // smlall za.d[w9, 4:7, vgx2], {z14.h-z15.h}, z11.h: SME2 and I16I64
    DIANA_TEST_ASSERT(DecodeA64(0xc16b21c1, &result, &sme2) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA64_IsUndefined(&result) && DianaA64_GetWordClass(&result) == DIANA_A64_WORD_DISABLED);
    DIANA_TEST_ASSERT(DecodeA64(0xc16b21c1, &result, &i16i64) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!DianaA64_IsUndefined(&result));
}

// every preset against an explicit list of the features it has: one instruction per feature is decoded by its own
// name, or hidden (".inst" or the generic form: axflag prints as msr). Change a list only on purpose
struct ArmProfileProbe
{
    const char * pFeature;
    unsigned int word;
    const char * pName;
};

static const ArmProfileProbe g_profileProbes[] =
{
    {"crc", 0x1ac24020, "crc32b"},     {"lse", 0xf8200020, "ldadd"},       {"rdm", 0x6f72d820, "sqrdmlah"},
    {"lor", 0x08df7c20, "ldlarb"},     {"fp16", 0x1ee20820, "fmul"},       {"fhm", 0x0e22ec20, "fmlal"},
    {"dotprod", 0x4e829420, "sdot"},   {"aes", 0x4e284820, "aese"},        {"sha2", 0x5e024020, "sha256h"},
    {"sha3", 0xce020c20, "eor3"},      {"sm4", 0xcec08420, "sm4e"},        {"pauth", 0xdac103e0, "pacia"},
    {"rcpc", 0xb8bfc020, "ldapr"},     {"jscvt", 0x1e7e0020, "fjcvtzs"},   {"fcma", 0x6ec2f420, "fcadd"},
    {"rcpc2", 0x19500020, "ldapurb"},  {"flagm", 0xba008402, "rmif"},      {"mte", 0x9adf1020, "irg"},
    {"sb", 0xd50330ff, "sb"},          {"frintts", 0x4e21e820, "frint32z"}, {"flagm2", 0xd500405f, "axflag"},
    {"bf16", 0x6e42fc20, "bfdot"},     {"i8mm", 0x4e82a420, "smmla"},      {"wfxt", 0xd5031003, "wfet"},
    {"ls64", 0xf83fd020, "ld64b"},     {"mops", 0x19010440, "cpyfp"},      {"hbc", 0x540000b1, "bc.cond"},
    {"cssc", 0x5ac02020, "abs"},       {"rprfm", 0xf8a24b18, "rprfm"},     {"gcs", 0xd91f0c20, "gcsstr"},
    {"lse128", 0x19218040, "swpp"},    {"rcpc3", 0x99411840, "ldiapp"},    {"the", 0x19200841, "rcwcas"},
    {"d128", 0xd5782000, "mrrs"},      {"xs", 0xd503323f, "dsb"},          {"pauth_lr", 0xdac1907e, "autiasppcr"},
    {"cmpbr", 0x74020081, "cbgt"},     {"tev", 0xd6ff03e0, "texit"},
    // M5. a|b: decoded when the preset has any of them; a+b: all of them
    {"sve|sme", 0x0480184a, "add"},    {"sme", 0x8085c081, "fmopa"},       {"sve", 0x65820c20, "ftsmul"},
    {"sve2", 0x45a2c020, "histcnt"},   {"sve_bitperm", 0x4582b420, "bdep"}, {"sme2", 0xc0480001, "zero"},
    {"sme_i16i64", 0xa0c32040, "smopa"}, {"sme_f64f64", 0x80c32040, "fmopa"}, {"aes+sve2", 0x4522e020, "aese"},
    {"f64mm", 0x64e2e420, "fmmla"},    {"f32mm", 0x64a2e420, "fmmla"},     {"i8mm+sve", 0x45029820, "smmla"},
    {"bf16+sve|sme", 0x64628020, "bfdot"}, {"sme2|sve2p1", 0x25a14c10, "whilelo"},
};

static void test_arm64_profile_presets()
{
    // the features of each preset that have a probe, separated and ended by spaces
    static const struct { const char * pName; const char * pFeatures; } presets[] =
    {
        {"armv8.0", " "},
        {"armv8.2", " crc lse rdm lor "},
        {"armv8.5", " crc lse rdm lor dotprod pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 "},
        {"armv9.0", " crc lse rdm lor dotprod pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 sve sve2 "},
        {"rpi3", " crc "},
        {"rpi4", " crc "},
        {"rpi5", " crc lse rdm lor fp16 dotprod aes sha2 rcpc "},
        {"android-arm64", " "},
        {"apple-m1", " crc lse rdm lor fp16 fhm dotprod aes sha2 sha3 pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 "},
        {"apple-m2", " crc lse rdm lor fp16 fhm dotprod aes sha2 sha3 pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 "
                     "bf16 i8mm "},
        {"apple-m4", " crc lse rdm lor fp16 fhm dotprod aes sha2 sha3 pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 "
                     "bf16 i8mm wfxt xs sme sme2 sme_i16i64 sme_f64f64 "},
        {"cortex-x1", " crc lse rdm lor fp16 dotprod aes sha2 rcpc "},
        {"cortex-x4", " crc lse rdm lor fp16 fhm dotprod aes sha2 pauth rcpc jscvt fcma rcpc2 flagm mte sb frintts flagm2 "
                      "bf16 i8mm wfxt xs sve sve2 sve_bitperm "},
        {"graviton2", " crc lse rdm lor fp16 dotprod aes sha2 rcpc "},
        {"graviton3", " crc lse rdm lor fp16 fhm dotprod aes sha2 sha3 sm4 pauth rcpc jscvt fcma rcpc2 flagm bf16 i8mm sve "},
        {"graviton4", " crc lse rdm lor fp16 fhm dotprod aes sha2 sha3 pauth rcpc jscvt fcma rcpc2 flagm sb frintts flagm2 "
                      "bf16 i8mm sve sve2 sve_bitperm "},
        // M6 step 6: AArch32 levels and CPUs (no A64), Cortex-A53/A72 in both modes
        {"armv6", " "}, {"armv7", " "}, {"armv7ve", " "}, {"rpi1", " "}, {"rpi2", " "}, {"android-armv7", " "},
        {"cortex-a7", " "}, {"cortex-a53", " crc "}, {"cortex-a72", " crc "},
    };
    int count = 0;
    DianaArm_GetProfiles(&count);
    // every preset is listed here, besides "all"
    DIANA_TEST_ASSERT(count == (int)(sizeof(presets)/sizeof(presets[0])) + 1);
    for (size_t i = 0; i < sizeof(presets)/sizeof(presets[0]); ++i)
    {
        const DianaArmProfile * pProfile = DianaArm_FindProfile(presets[i].pName);
        DIANA_TEST_ASSERT(pProfile != 0);
        if (!pProfile)
            continue;
        for (size_t j = 0; j < sizeof(g_profileProbes)/sizeof(g_profileProbes[0]); ++j)
        {
            const ArmProfileProbe & probe = g_profileProbes[j];
            // "a+b|c": every part joined by + is needed, a part a|b needs one of its names
            int expected = 1;
            std::string parts = std::string(probe.pFeature) + "+";
            for (size_t start = 0, plus = 0; (plus = parts.find('+', start)) != std::string::npos; start = plus + 1)
            {
                int any = 0;
                std::string names = parts.substr(start, plus - start) + "|";
                for (size_t from = 0, bar = 0; (bar = names.find('|', from)) != std::string::npos; from = bar + 1)
                {
                    std::string key = " " + names.substr(from, bar - from) + " ";
                    any |= strstr(presets[i].pFeatures, key.c_str()) != 0;
                }
                expected &= any;
            }
            DianaParserResult result;
            DIANA_TEST_ASSERT(DecodeA64(probe.word, &result, pProfile) == DI_SUCCESS);
            int decoded = !DianaA64_IsUndefined(&result) && !strcmp(result.pInfo->m_pGroupInfo->m_pName, probe.pName);
            if (decoded != expected)
                printf("profile %s, %s (%s): expected %s\n", presets[i].pName, probe.pFeature, probe.pName,
                       expected ? "decoded" : "hidden");
            DIANA_TEST_ASSERT(decoded == expected);
        }
    }
    // "all" decodes every probe
    for (size_t j = 0; j < sizeof(g_profileProbes)/sizeof(g_profileProbes[0]); ++j)
    {
        DianaParserResult result;
        DIANA_TEST_ASSERT(DecodeA64(g_profileProbes[j].word, &result, DianaArm_FindProfile("all")) == DI_SUCCESS);
        DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, g_profileProbes[j].pName));
    }
}

void test_arm64()
{
    DIANA_TEST(test_arm64_profile_presets());
    DIANA_TEST(test_arm64_text());
    DIANA_TEST(test_arm64_operands());
    DIANA_TEST(test_arm64_jumps());
    DIANA_TEST(test_arm64_branch_text());
    DIANA_TEST(test_arm64_word_classes());
    DIANA_TEST(test_arm64_profiles());
    DIANA_TEST(test_arm64_misc());
    DIANA_TEST(test_arm64_abi());
    DIANA_TEST(test_arm64_simd_operands());
    DIANA_TEST(test_arm64_simd_text());
    DIANA_TEST(test_arm64_simd_profiles());
    DIANA_TEST(test_arm64_sve_operands());
    DIANA_TEST(test_arm64_sve_profiles());
    DIANA_TEST(test_arm64_sme2_profiles());
}
